import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../app/routes.dart';
import '../../app/ui/ui.dart';
import '../../data/repos/leagues_repo.dart';
import '../../widgets/signed_in_scope.dart';

/// Name a league; the invite code is generated by the database.
class CreateLeagueScreen extends ConsumerStatefulWidget {
  const CreateLeagueScreen({super.key});

  @override
  ConsumerState<CreateLeagueScreen> createState() => _CreateLeagueScreenState();
}

class _CreateLeagueScreenState extends ConsumerState<CreateLeagueScreen> {
  final _name = TextEditingController();
  bool _busy = false;
  String? _error;

  @override
  void dispose() {
    _name.dispose();
    super.dispose();
  }

  Future<void> _create() async {
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      final league = await ref
          .read(leaguesRepoProvider)
          .createLeague(_name.text);
      ref.invalidate(refreshMyLeaguesProvider);
      Haptics.success();
      if (mounted) context.go(Routes.league(league.id));
    } on ArgumentError catch (e) {
      setState(() => _error = e.message as String?);
    } catch (e) {
      debugPrint('createLeague: $e');
      setState(
        () => _error =
            'Could not create it right now. We will try again when you are '
            'back online.',
      );
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('New league')),
      body: SignedInScope(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(
            Space.gutter,
            Space.lg,
            Space.gutter,
            Space.gutter,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              TextField(
                controller: _name,
                autofocus: true,
                maxLength: 40,
                textCapitalization: TextCapitalization.words,
                decoration: InputDecoration(
                  labelText: 'Name your league',
                  hintText: 'The Boys, Carpool Crew, Family',
                  errorText: _error,
                ),
                onSubmitted: (_) => _busy ? null : _create(),
              ),
              const SizedBox(height: Space.md),
              Text(
                'Up to 30 friends, Monday to Sunday. XP comes from how well '
                'you drive, never how far or how fast.',
                style: context.caption,
              ),
              const SizedBox(height: Space.xl),
              PrimaryButton(
                label: 'Create league',
                icon: Icons.emoji_events_outlined,
                busy: _busy,
                onPressed: _create,
              ),
            ],
          ),
        ),
      ),
    );
  }
}
